extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	if not check("file_exists", FileAccess.file_exists("res://story/intro.json"), "Il file res://story/intro.json deve esistere"):
		return

	var file := FileAccess.open("res://story/intro.json", FileAccess.READ)
	if not check("file_open", file != null, "Il file res://story/intro.json deve potersi aprire"):
		return

	var json := JSON.new()
	var parse_err := json.parse(file.get_as_text())
	if not check("json_parse", parse_err == OK, "Il file intro.json deve contenere JSON valido: " + json.get_error_message()):
		return

	var data = json.data
	if not check("data_dict", typeof(data) == TYPE_DICTIONARY, "La radice del JSON deve essere un oggetto Dictionary"):
		return

	check("has_title", data.has("title") and typeof(data["title"]) == TYPE_STRING, "L'oggetto radice deve avere una chiave 'title' di tipo stringa")

	if not check("has_lines", data.has("lines") and typeof(data["lines"]) == TYPE_ARRAY, "L'oggetto radice deve avere una chiave 'lines' di tipo Array"):
		return

	var lines: Array = data["lines"]
	check("count_lines", lines.size() >= 20, "L'array 'lines' deve contenere almeno 20 battute (trovate: %d)" % lines.size())

	var valid_format := true
	for i in range(lines.size()):
		var line = lines[i]
		if typeof(line) != TYPE_DICTIONARY or not line.has("speaker") or not line.has("text") or typeof(line["speaker"]) != TYPE_STRING or typeof(line["text"]) != TYPE_STRING:
			valid_format = false
			break

	check("valid_lines_format", valid_format, "Ogni elemento dell'array 'lines' deve essere un oggetto con chiavi 'speaker' e 'text' di tipo stringa")

